这里有一个示例的Jenkins文件，这将部署任何其他的库。

def region = 'eu-west-1'
def lambdazip = 'alarm-ingest-lambda-code.zip'
def s3LambdaPath = 'smtp-alarm-ingestion/' + lambdazip

pipeline {
 parameters {
 booleanParam(name: 'FORCE\_DEPLOY', defaultValue: false, description: 'Deploy code+infra. Ignore any other logic saying not to')
 string(name: 'ENVIRONMENT', defaultValue: '', description: 'The environment to deploy to. prod, uat or dev')
 string(name: 'TENANT', defaultValue: '', description: 'The tenant to deploy to (leave blank for all tenants)')
 }

 environment {
 GITHUB\_CREDS = credentials('sbl-aws-github')
 GITHUB\_TOKEN = "${env.GITHUB\_CREDS\_PSW}"
 }

 agent none

 stages {
 stage("Prepare"){
 agent { label 'default-java' }
 steps {
 script {
 dir('smart-vue-config') {
 git(
 branch: 'master',
 credentialsId: 'sbl-aws-github',
 url: 'https://github.com/smart-buildings/smart-vue-config.git'
 )
 }
 def envs = load "smart-vue-config/.ci/environments.groovy"
 (TARGET\_ENVIRONMENT, DEPLOY) = envs.deployWhere(env.BRANCH\_NAME, env.CHANGE\_BRANCH, env.CHANGE\_TARGET, params.FORCE\_DEPLOY, params.ENVIRONMENT)
 println("TARGET\_ENVIRONMENT: ${TARGET\_ENVIRONMENT}\nDEPLOY: ${DEPLOY}")
 def TENANT\_CONFIGS\_PARAMS = [
 TARGET\_ENVIRONMENT: TARGET\_ENVIRONMENT,
 agent: '.ci/Jenkins/agent\_python.k8s.yaml',
 FORCE\_TENANT: params.TENANT
 ]
 tenHelper = load "smart-vue-config/.ci/tenants.groovy"
 tenHelper.init(TENANT\_CONFIGS\_PARAMS)
 FORCE\_DEPLOY = tenHelper.isBuildTriggeredByConfigs(currentBuild) || params.FORCE\_DEPLOY
 PIPELINE\_NAME = envs.jobName()
 SLACK\_CHANNEL = "#smart-vue-${TARGET\_ENVIRONMENT}"
 LAST\_CHANGE\_AUTHOR = sh(script: "git show -s --pretty=%an", returnStdout: true).trim()
 IS\_PR = env.CHANGE\_ID as Boolean
 utils = load "smart-vue-config/.ci/utils.groovy"
 }
 }
 }

 stage("Slack notification") {
 when {
 expression { return DEPLOY }
 }
 steps {
 slackSend(
 channel: SLACK\_CHANNEL,
 color: '#C5C5C5',
 message: "\*${PIPELINE\_NAME}\* build #${currentBuild.number} is now deploying to ${TARGET\_ENVIRONMENT}. The last commit was made by ${LAST\_CHANGE\_AUTHOR}. You can watch the progress <${env.JOB\_URL}|here>."
 )
 }
 }

 stage('Run') {
 agent {
 kubernetes {
 cloud 'kubernetes'
 yamlFile '.ci/Jenkins/agent.k8s.yaml'
 }
 }
 environment {
 //TARGET\_ENVIRONMENT dependant
 AWS\_CREDS = credentials("${TARGET\_ENVIRONMENT}-smartbuildings-awsmigration-aws")
 SCEPTRE\_ENV\_FILE="infrastructure/sceptre-variables/${TARGET\_ENVIRONMENT}.yaml"
 //bucket was created by cloudformation-templates/landing zone
 BUCKET = "s3-euw1-${TARGET\_ENVIRONMENT}-lambdas"
 GITHUB\_CREDS = credentials('sbl-aws-github')
 GITHUB\_TOKEN = "${env.GITHUB\_CREDS\_PSW}"
 }

 stages {
 stage("App pipeline") {
 when {
 anyOf {
 changeset 'src/\*\*'
 changeset 'Jenkinsfile'
 expression { return FORCE\_DEPLOY }
 expression { return IS\_PR }
 }
 }
 stages {
 stage("App setup") {
 steps {
 container(name: 'node') {
 sh "npm config set '//npm.pkg.github.com/:\_authToken=${GITHUB\_TOKEN}'"
 sh "npm ci"
 }
 }
 }

 stage("App test") {
 steps {
 container(name: 'node') {
 sh "npm test"
 }
 }
 }

 stage("App build") {
 when {
 expression { return DEPLOY }
 }
 steps {
 container(name: 'node') {
 sh "npm run build"
 zip zipFile: "${lambdazip}", archive: false, dir: "dist"
 }
 }
 }

 stage("App Push") {
 when {
 expression { return DEPLOY }
 }
 steps {
 container(name: 'python') {
 sh "pip install awscli"
 sh "aws s3 cp ${lambdazip} s3://${env.BUCKET}/${s3LambdaPath}"
 }
 }
 }
 }
 }

 stage("Infrastructure pipeline") {
 when {
 anyOf{
 changeset 'infrastructure/\*\*'
 changeset 'Jenkinsfile'
 changeset '.ci/\*\*'
 expression { return FORCE\_DEPLOY }
 }
 }
 stages {
 stage("Infrastructure validate") {
 when {
 expression { return !DEPLOY }
 }
 steps {
 container(name: 'python') {
 sh "apt update && apt install gcc git -y"
 sh "pip install pre-commit"
 sh "pip install 'sceptre>=2.0,<3.0'"
 sh "pip install markupsafe==2.0.1"
 sh "pre-commit autoupdate"
 sh "pre-commit run --all-files"
 script {
 tenHelper.unstashConfigs()
 def configs = tenHelper.getTenantConfigs()
 configs.each {
 sh "sceptre --dir infrastructure \
 --var-file ${env.SCEPTRE\_ENV\_FILE} \
 --var-file ${it} \
 --var lambda\_s3\_key=${s3LambdaPath} \
 --var lambda\_s3\_bucket=${env.BUCKET} \
 validate ''"
 }
 }
 }
 }
 }

 stage("Infrastructure deploy") {
 when {
 expression { return DEPLOY }
 }
 steps {
 script {
 def param = [
 agent: '.ci/Jenkins/agent\_python.k8s.yaml',
 envFile: env.SCEPTRE\_ENV\_FILE,
 lambda\_s3\_key: s3LambdaPath,
 lambda\_s3\_bucket: env.BUCKET,
 ]

 parallel deployTenants( param, tenHelper )
 }
 }
 }
 }
 }

 stage("Lambda pipeline") {
 when {
 expression { return DEPLOY }
 anyOf {
 changeset 'src/\*\*'
 changeset 'Jenkinsfile'
 expression { return FORCE\_DEPLOY }
 }
 }
 stages {
 stage("Lambda update") {
 steps {
 container(name: 'python') {
 sh "pip install awscli -q"
 script {
 tenHelper.unstashConfigs()
 def tenantsF = []
 def tenanNames = tenHelper.getTenantNames();
 tenanNames.each {
 tenantsF.add([
 tenantName: it,
 functionName: "lmd-euw1-${TARGET\_ENVIRONMENT}-${it}-ingest-alarm",
 ])
 }
 tenantsF.each {
 sh "aws lambda update-function-code \
 --function-name ${it.functionName} \
 --s3-bucket ${env.BUCKET} \
 --s3-key ${s3LambdaPath} \
 --region ${region}"
 }
 }
 }
 }
 }
 }
 }

 }
 }

 post {
 success {
 script {
 if (DEPLOY) {
 slackSend(
 channel: SLACK\_CHANNEL,
 color: 'good',
 message: "\*${PIPELINE\_NAME}\* build #${currentBuild.number} deployment to ${TARGET\_ENVIRONMENT} succeeded. ${LAST\_CHANGE\_AUTHOR} please test your changes."
 )
 }
 }
 }

 failure {
 script {
 if (DEPLOY) {
 slackSend(
 channel: SLACK\_CHANNEL,
 color: 'danger',
 message: "@channel \*${PIPELINE\_NAME}\* build #${currentBuild.number} failed to deploy to ${TARGET\_ENVIRONMENT}. ${LAST\_CHANGE\_AUTHOR} please review the logs <${env.JOB\_URL}|here>."
 )
 }
 }
 }
 }
}

/\*\*
\* 创建一组脚本管道。每个新管道部署一个租户的基础设施
 \* @param p.envFile sceptre env配置文件（sceptre-variables/dev.yaml）
 \* @param p.lambda\_s3\_key S3文件夹
 \* @param p.lambda\_s3\_bucket S3对象名称
\*/
def deployTenants(p, tenHelper) {
 tenHelper.unstashConfigs()
 def configs = tenHelper.getTenantConfigs()
 def builders = [:]
 for (tenant\_config in configs) {
 def config = tenant\_config
 def stageName = tenHelper.getTenantFromFileName (config)
 builders[stageName] = {
 podTemplate(yaml: readFile(p.agent)) {
 node(POD\_LABEL) {
 stage(stageName) {
 checkout scm
 tenHelper.unstashConfigs()
 container('python') {
 sh "pip install 'sceptre>=2.0,<3.0'"
 sh "pip install markupsafe==2.0.1"
 sh """
 sceptre --dir infrastructure \
 --var-file ${p.envFile} \
 --var-file ${config} \
 --var lambda\_s3\_key=${p.lambda\_s3\_key} \
 --var lambda\_s3\_bucket=${p.lambda\_s3\_bucket} \
 launch -y ''
 """
 }
 }
 }
 }
 }
 }
 return builders
}
